import { syncSelection } from "./tableDefs/streamingExport";
export { syncSelection } from "./tableDefs/streamingExport";
import { defineSchema, defineTable } from "convex/server";
import { v } from "convex/values";
import deploymentAuditLogTable, {
  systemStopState,
} from "./tableDefs/deploymentAuditLogTable";
import { snapshotImportsTable } from "./tableDefs/snapshotImport";
import { awsLambdaVersionsTable } from "./tableDefs/awsLambdaVersions";

// This file isn't autogenerated, it must be manually synced with system tables.
// `../systemSchema.json` snapshots these definitions for the backend; regenerate
// it with `npm run generate-system-schema`.

export const udfType = v.union(
  v.literal("Query"),
  v.literal("Mutation"),
  v.literal("Action"),
  v.literal("HttpAction"),
);

const schemaState = v.union(
  v.object({ state: v.literal("pending") }),
  v.object({ state: v.literal("validated") }),
  v.object({ state: v.literal("active") }),
  v.object({
    state: v.literal("failed"),
    error: v.string(),

    // The table that failed validation. Missing on schemas that failed before
    // it was recorded.
    table_name: v.optional(v.union(v.string(), v.null())),
  }),
  v.object({ state: v.literal("overwritten") }),
);

const schemaMetadata = v.object({
  state: schemaState,
  // This is a string because the rust code serializes the DatabaseSchema structure to a string.
  schema: v.optional(v.string()),
});

export const udfVisibility = v.union(
  v.object({ kind: v.literal("public") }),
  v.object({ kind: v.literal("internal") }),
);

const analyzedSourcePosition = v.object({
  path: v.string(),
  start_lineno: v.int64(),
  start_col: v.int64(),
});

const analyzedFunction = v.object({
  name: v.string(),

  // Older modules have `lineno` and newer ones `pos`, which is null when the
  // analyzer can't find the function's source position.
  lineno: v.optional(v.int64()),
  pos: v.optional(v.union(analyzedSourcePosition, v.null())),

  udfType,
  visibility: v.optional(v.union(v.null(), udfVisibility)),

  // Serialized validators. Missing on modules analyzed before validators
  // existed, and null once such a module is rewritten without being
  // re-analyzed. Rust reads both as unvalidated.
  args: v.optional(v.union(v.string(), v.null())),
  returns: v.optional(v.union(v.string(), v.null())),
});

const analyzedHttpRoute = v.object({
  route: v.object({
    path: v.string(),
    method: v.string(),
  }),

  // Older modules have `lineno` and newer ones `pos`, which is null when the
  // analyzer can't find the route's source position.
  lineno: v.optional(v.int64()),
  pos: v.optional(v.union(analyzedSourcePosition, v.null())),
});

// Null when the developer leaves the minute to the backend, which picks one
// per job to spread load.
const minuteUTC = v.optional(v.union(v.int64(), v.null()));

const CronSchedule = v.union(
  v.object({
    type: v.literal("interval"),
    seconds: v.int64(),
  }),
  v.object({
    type: v.literal("hourly"),
    minuteUTC,
  }),
  v.object({
    type: v.literal("daily"),
    minuteUTC,
    hourUTC: v.int64(),
  }),
  v.object({
    type: v.literal("weekly"),
    dayOfWeek: v.int64(),
    hourUTC: v.int64(),
    minuteUTC,
  }),
  v.object({
    type: v.literal("monthly"),
    day: v.int64(),
    minuteUTC,
    hourUTC: v.int64(),
  }),
  v.object({
    type: v.literal("cron"),
    cronExpr: v.string(),
  }),
);

const analyzedCronSpec = v.object({
  udfPath: v.string(),
  udfArgs: v.bytes(),
  cronSchedule: CronSchedule,
});

const mappedModule = v.object({
  sourceIndex: v.union(v.int64(), v.null()),
  functions: v.array(analyzedFunction),
  httpRoutes: v.union(v.array(analyzedHttpRoute), v.null()),
  cronSpecs: v.optional(
    v.union(
      v.array(
        v.object({
          identifier: v.string(),
          spec: analyzedCronSpec,
        }),
      ),
      v.null(),
    ),
  ),
});

const analyzedModule = v.object({
  functions: v.array(analyzedFunction),
  httpRoutes: v.union(v.array(analyzedHttpRoute), v.null()),
  cronSpecs: v.optional(
    v.union(
      v.array(
        v.object({
          identifier: v.string(),
          spec: analyzedCronSpec,
        }),
      ),
      v.null(),
    ),
  ),
  sourceMapped: v.union(mappedModule, v.null()),
  // Written only when true.
  reuseContext: v.optional(v.boolean()),
});

const exportRequestor = v.union(
  v.literal("snapshotExport"),
  v.literal("cloudBackup"),
);

const exportFormat = v.object({
  format: v.literal("zip"),
  include_storage: v.boolean(),
});

// Null for the app.
const exportComponent = v.union(v.string(), v.null());

export const completedExport = v.object({
  state: v.literal("completed"),
  complete_ts: v.int64(),
  expiration_ts: v.int64(),
  start_ts: v.int64(),

  // Legacy field that Rust ignores.
  tables: v.optional(v.array(v.array(v.string()))),

  zip_object_key: v.string(),
  format: exportFormat,
  component: exportComponent,
  requestor: exportRequestor,

  // Size of the zip in bytes. Missing on exports completed before it was
  // recorded.
  size: v.optional(v.int64()),
});

const cronJobStatus = v.union(
  v.object({
    type: v.literal("success"),
    result: v.any(),
  }),
  v.object({
    type: v.literal("err"),
    error: v.any(),
  }),
  v.object({
    type: v.literal("canceled"),
    num_canceled: v.int64(),
  }),
);

export const integrationState = v.union(
  v.object({
    type: v.literal("pending"),
  }),
  v.object({
    type: v.literal("failed"),
    reason: v.string(),
  }),
  v.object({
    type: v.literal("active"),
  }),
  v.object({
    type: v.literal("deleting"),
  }),
  // Set on active integrations while the backend restarts them.
  v.object({
    type: v.literal("restarting"),
  }),
);

// The subscribable log stream topics.
export const logTopic = v.union(
  v.literal("console"),
  v.literal("function_execution"),
  v.literal("audit_log"),
  v.literal("scheduler_stats"),
  v.literal("scheduled_job_lag"),
  v.literal("current_storage_usage"),
  v.literal("concurrency_stats"),
  v.literal("storage_api_bandwidth"),
  v.literal("ai_gateway_usage"),
  v.literal("log_stream_egress"),
  v.literal("custom_audit"),
  v.literal("s3_export_stats"),
);

// The topics a log stream is subscribed to. Absent means subscribed to all
// topics, including ones added in the future.
const subscribedTopics = v.optional(v.array(logTopic));

// Rust writes unset optional config fields as null.
const optionalNullableString = v.optional(v.union(v.string(), v.null()));

export const datadogConfig = v.object({
  type: v.literal("datadog"),
  siteLocation: v.union(
    v.literal("US1"),
    v.literal("US3"),
    v.literal("US5"),
    v.literal("EU"),
    v.literal("US1_FED"),
    v.literal("AP1"),
  ),
  ddApiKey: v.string(),
  ddTags: v.array(v.string()),
  service: optionalNullableString,
  version: v.optional(v.union(v.literal("1"), v.literal("2"))),
  topics: subscribedTopics,
});

export const webhookConfig = v.object({
  type: v.literal("webhook"),
  url: v.string(),
  format: v.union(v.literal("json"), v.literal("jsonl")),
  hmacSecret: v.string(),
  topics: subscribedTopics,
});

export const axiomConfig = v.object({
  type: v.literal("axiom"),
  apiKey: v.string(),
  datasetName: v.string(),
  attributes: v.array(
    v.object({
      key: v.string(),
      value: v.string(),
    }),
  ),
  version: v.optional(v.union(v.literal("1"), v.literal("2"))),
  ingestUrl: optionalNullableString,
  topics: subscribedTopics,
});

export const sentryConfig = v.object({
  type: v.literal("sentry"),
  dsn: v.string(),
  tags: v.optional(v.union(v.record(v.string(), v.string()), v.null())),
  version: v.optional(v.union(v.literal("1"), v.literal("2"))),
});

export const postHogLogsConfig = v.object({
  type: v.literal("postHogLogs"),
  apiKey: v.string(),
  host: optionalNullableString,
  serviceName: optionalNullableString,
  topics: subscribedTopics,
});

export const postHogErrorTrackingConfig = v.object({
  type: v.literal("postHogErrorTracking"),
  apiKey: v.string(),
  host: optionalNullableString,
});

const s3ExportProgress = v.union(
  v.object({
    type: v.literal("snapshotting"),
    numTablesSynced: v.int64(),
    totalTables: v.int64(),
    currentComponent: v.string(),
    currentTable: v.string(),
    numDocumentsInCurrentTable: v.int64(),
    totalDocumentsInCurrentTable: v.union(v.int64(), v.null()),
    numDocumentsSynced: v.int64(),
    totalDocuments: v.union(v.int64(), v.null()),
  }),
  v.object({ type: v.literal("stale"), ts: v.int64() }),
  v.object({ type: v.literal("upToDate"), ts: v.int64() }),
);

export const s3ExportConfig = v.object({
  type: v.literal("s3Export"),
  bucket: v.string(),
  region: v.string(),
  prefix: optionalNullableString,
  accessKeyId: v.optional(v.string()),
  secretAccessKey: v.optional(v.string()),
  // Empty until the admin pastes the ARN from their CloudFormation stack.
  roleArn: v.optional(v.string()),
  roleExternalId: v.optional(v.string()),
  selection: syncSelection,

  // Left on configs written before the sync period was removed and the
  // export progress moved to `_s3_export_state`. Rust ignores them.
  period: v.optional(
    v.union(v.literal("continuous"), v.literal("hourly"), v.literal("daily")),
  ),
  cursor: v.optional(v.union(v.string(), v.null())),
  progress: v.optional(v.union(s3ExportProgress, v.null())),
});

export const integrationConfig = v.union(
  datadogConfig,
  webhookConfig,
  axiomConfig,
  sentryConfig,
  postHogLogsConfig,
  postHogErrorTrackingConfig,
  s3ExportConfig,
);

const integrationsTable = defineTable({
  status: integrationState,
  config: integrationConfig,
});

const userStopState = v.union(v.literal("none"), v.literal("paused"));

const usageLimitStopState = v.union(v.literal("none"), v.literal("disabled"));

export const backendState = v.object({
  system: systemStopState,

  // Not set on older documents. `SerializedBackendState` defaults it to
  // "none", but reads from JS don't get this default value.
  usage_limit: v.optional(usageLimitStopState),

  user: userStopState,
});

const backendStateTable = defineTable(backendState);

export const cronJobState = v.union(
  v.object({ type: v.literal("pending") }),
  v.object({
    type: v.literal("inProgress"),
    request_id: v.string(),
    execution_id: v.string(),
  }),
);

// Fields with `v.optional` below are missing on index documents last written
// before they were added.

// Rust serializes these cursors as arrays of byte values.
const tableScanCursor = v.array(v.int64());

const textIndexSegment = v.object({
  segment_key: v.string(),
  id_tracker_key: v.string(),
  deleted_terms_table_key: v.string(),
  alive_bitset_key: v.string(),
  num_indexed_documents: v.int64(),
  num_deleted_documents: v.int64(),
  size_bytes_total: v.int64(),
  id: v.string(),
});

// Rust keeps snapshot data in a format it doesn't recognize (for example, one
// written by a newer backend) as an opaque object and writes it back unchanged.
const unknownIndexSnapshotData = v.record(v.string(), v.any());

const textIndexSnapshot = {
  data: v.union(
    v.object({
      data_type: v.literal("MultiSegment"),
      segments: v.array(textIndexSegment),
    }),
    unknownIndexSnapshotData,
  ),
  ts: v.int64(),
  version: v.int64(),
};

const textIndexOnDiskState = v.union(
  v.object({
    state: v.literal("backfilling"),
    staged: v.optional(v.union(v.boolean(), v.null())),
  }),
  v.object({
    state: v.literal("backfilling2"),
    segments: v.optional(v.union(v.array(textIndexSegment), v.null())),
    // Rust sets both cursor fields or neither (`cursor` is null), and fails to
    // read anything else.
    cursor: v.optional(
      v.union(
        v.object({
          table_scan_cursor: tableScanCursor,
          last_segment_ts: v.int64(),
        }),
        v.null(),
      ),
    ),
    staged: v.optional(v.union(v.boolean(), v.null())),
  }),
  v.object({
    state: v.literal("backfilled2"),
    snapshot: v.object(textIndexSnapshot),
    staged: v.boolean(),
  }),
  v.object({
    // "backfilled" is the legacy name of "snapshotted".
    state: v.union(v.literal("backfilled"), v.literal("snapshotted")),
    ...textIndexSnapshot,
  }),
);

const vectorIndexSegment = v.object({
  segment_key: v.string(),
  id_tracker_key: v.string(),
  deleted_bitset_key: v.string(),
  num_vectors: v.int64(),
  num_deleted: v.int64(),
  id: v.string(),
});

const vectorIndexSnapshot = {
  data: v.union(
    v.object({
      data_type: v.literal("MultiSegment"),
      segments: v.array(vectorIndexSegment),
    }),
    unknownIndexSnapshotData,
  ),
  ts: v.int64(),
};

const vectorIndexBackfilling = {
  state: v.literal("backfilling"),
  segments: v.optional(v.union(v.array(vectorIndexSegment), v.null())),
  staged: v.optional(v.union(v.boolean(), v.null())),
};

const vectorIndexOnDiskState = v.union(
  // Rust sets both cursor fields or neither, and fails to read anything else.
  v.object({
    ...vectorIndexBackfilling,
    table_scan_cursor: tableScanCursor,
    last_segment_ts: v.int64(),
  }),
  v.object({
    ...vectorIndexBackfilling,
    table_scan_cursor: v.optional(v.null()),
    last_segment_ts: v.optional(v.null()),
  }),

  v.object({
    state: v.literal("backfilled2"),
    snapshot: v.object(vectorIndexSnapshot),
    staged: v.boolean(),
  }),
  v.object({
    // "backfilled" is the legacy name of "snapshotted".
    state: v.union(v.literal("backfilled"), v.literal("snapshotted")),
    ...vectorIndexSnapshot,
  }),
);

export default defineSchema({
  _tables: defineTable({
    name: v.string(),
    number: v.int64(),
    state: v.union(
      v.literal("active"),
      v.literal("deleting"),
      v.literal("hidden"),
    ),
    namespace: v.optional(
      v.object({
        kind: v.literal("byComponent"),
        id: v.string(),
      }),
    ),
  }).index("by_name", ["name"]),
  _index: defineTable({
    table_id: v.string(),
    descriptor: v.string(),
    config: v.union(
      v.object({
        type: v.literal("database"),
        fields: v.array(v.string()),
        persistenceIndexId: v.optional(v.int64()),
        onDiskState: v.union(
          v.object({
            type: v.literal("Backfilling"),
            backfillState: v.object({
              // Missing on documents written before these were tracked.
              indexCreatedLowerBound: v.optional(v.int64()),
              retentionStarted: v.optional(v.boolean()),
              staged: v.optional(v.boolean()),
            }),
          }),
          v.object({
            type: v.literal("Backfilled2"),
            staged: v.optional(v.boolean()),
          }),
          v.object({
            type: v.literal("Enabled"),
          }),
          v.object({
            type: v.literal("Disabled"),
          }),
        ),
      }),
      v.object({
        type: v.literal("search"),
        searchField: v.string(),
        filterFields: v.array(v.string()),
        onDiskState: textIndexOnDiskState,
      }),
      v.object({
        type: v.literal("vector"),
        vectorField: v.string(),
        dimensions: v.int64(),
        filterFields: v.array(v.string()),
        onDiskState: vectorIndexOnDiskState,
      }),
    ),
  }),
  _index_backfills: defineTable({
    indexId: v.id("_index"),
    numDocsIndexed: v.int64(),
    totalDocs: v.union(v.int64(), v.null()),
    // Null for search and vector indexes, which keep their backfill state in
    // `_index`. Missing on backfills that started before checkpointing.
    cursor: v.optional(
      v.union(
        v.object({
          snapshotTs: v.int64(),
          // ID of the last document indexed in the table being backfilled,
          // null before the first checkpoint.
          cursor: v.union(v.string(), v.null()),
        }),
        v.null(),
      ),
    ),
  }).index("by_index_id", ["indexId"]),
  _components: defineTable({
    definitionId: v.id("_component_definitions"),
    parent: v.union(v.id("_components"), v.null()),
    name: v.union(v.string(), v.null()),
    args: v.union(v.array(v.any()), v.null()),
    state: v.optional(v.union(v.literal("active"), v.literal("unmounted"))),
    // Absolute path this component's HTTP routes are served under: the app's
    // `httpPrefix` for the root, the mount path in the parent for children.
    httpPrefix: v.optional(v.union(v.string(), v.null())),
    // `[name, binding]` pairs for a child component and null for the app.
    // Missing on documents written before component env vars existed.
    env: v.optional(
      v.union(
        v.array(
          v.array(
            v.union(
              v.string(),
              v.object({ type: v.literal("value"), value: v.string() }),
              v.object({ type: v.literal("envVar"), name: v.string() }),
            ),
          ),
        ),
        v.null(),
      ),
    ),
  }),
  _modules: defineTable({
    path: v.string(),

    // Only on modules last written before mid-2024. Rust ignores them.
    latestVersion: v.optional(v.int64()),
    deleted: v.optional(v.boolean()),

    // Base64 SHA-256 of the module's source and source map.
    sha256: v.string(),

    analyzeResult: v.union(analyzedModule, v.null()),
    sourcePackageId: v.string(),
    environment: v.union(
      v.literal("node"),
      v.literal("isolate"),
      v.literal("invalid"),
    ),
  }).index("by_path", ["path"]),
  _auth: defineTable(
    v.union(
      v.object({
        type: v.literal("customJwt"),
        applicationID: v.union(v.string(), v.null()),
        issuer: v.string(),
        jwks: v.string(),
        // This is serialized *wrapped with double quotes* (!)
        algorithm: v.string(),
      }),
      v.object({
        applicationID: v.string(),
        domain: v.string(),
      }),
    ),
  ),
  _environment_variables: defineTable({
    name: v.string(),
    value: v.string(),
    // `true` for secrets, which are write-only: functions read them, admins
    // can't. `false` for variables explicitly made config variables, absent
    // while that is undecided.
    secret: v.optional(v.boolean()),
  }).index("by_name", ["name"]),
  _exports: defineTable(
    v.union(
      completedExport,
      v.object({
        // "failed" state is unused for new exports, because there are no
        // developer-error failure scenarios, so the export is retried until
        // success.
        state: v.literal("failed"),
        start_ts: v.int64(),
        failed_ts: v.int64(),
        format: exportFormat,
        component: exportComponent,
        requestor: exportRequestor,
      }),
      v.object({
        state: v.literal("in_progress"),
        start_ts: v.int64(),
        expiration_ts: v.int64(),
        format: exportFormat,
        component: exportComponent,
        requestor: exportRequestor,
        progress_message: v.optional(v.union(v.null(), v.string())),

        // Opaque state for resuming the export after a restart.
        resumption_token: v.optional(v.record(v.string(), v.any())),
      }),
      v.object({
        state: v.literal("requested"),
        expiration_ts: v.int64(),
        format: exportFormat,
        component: exportComponent,
        requestor: exportRequestor,
      }),
      v.object({
        state: v.literal("canceled"),
        start_ts: v.optional(v.union(v.null(), v.int64())),
        canceled_ts: v.int64(),
        format: exportFormat,
        component: exportComponent,
        requestor: exportRequestor,
      }),
    ),
  ).index("by_requestor", ["requestor"]),
  _deployment_audit_log: deploymentAuditLogTable,
  // A job stays pending until its scheduled time, so documents written by
  // older backends can lack any field with `v.optional`.
  _scheduled_jobs: defineTable({
    nextTs: v.optional(v.union(v.int64(), v.null())),
    completedTs: v.optional(v.union(v.int64(), v.null())),
    originalScheduledTs: v.optional(v.union(v.int64(), v.null())),
    udfPath: v.string(),
    state: v.union(
      v.object({ type: v.literal("pending") }),

      // Only actions go through this state.
      v.object({
        type: v.literal("inProgress"),
        request_id: v.string(),
        execution_id: v.string(),
      }),

      v.object({ type: v.literal("success") }),
      v.object({ type: v.literal("failed"), error: v.string() }),
      v.object({ type: v.literal("canceled") }),
    ),
    udfArgs: v.nullable(v.bytes()),
    argsId: v.optional(v.nullable(v.id("_scheduled_job_args"))),
    component: v.optional(v.nullable(v.string())),
    attempts: v.optional(
      v.nullable(
        v.object({
          systemErrors: v.int64(),
          occErrors: v.int64(),
        }),
      ),
    ),
  })
    .index("by_udf_path_and_next_event_ts", ["udfPath", "nextTs"])
    .index("by_next_ts", ["nextTs"]),
  _scheduled_job_args: defineTable({
    args: v.bytes(),
  }),
  _cron_jobs: defineTable({
    name: v.string(),
    cronSpec: analyzedCronSpec,

    // Legacy fields that Rust ignores. Crons last written before April 2025
    // kept their next run here, before it moved to `_cron_next_run`.
    state: v.optional(
      v.union(
        v.object({ type: v.literal("pending") }),
        v.object({ type: v.literal("inProgress") }),
        v.null(),
      ),
    ),
    prevTs: v.optional(v.union(v.int64(), v.null())),
    nextTs: v.optional(v.union(v.int64(), v.null())),
  }).index("by_name", ["name"]),
  _cron_next_run: defineTable({
    cronJobId: v.id("_cron_jobs"),
    state: cronJobState,
    prevTs: v.union(v.int64(), v.null()),
    nextTs: v.int64(),
  })
    .index("by_cron_job_id", ["cronJobId"])
    .index("by_next_ts", ["nextTs"]),
  _cron_job_logs: defineTable({
    name: v.string(),
    ts: v.int64(),
    udfPath: v.string(),
    udfArgs: v.bytes(),
    status: cronJobStatus,
    logLines: v.object({
      logLines: v.array(v.string()),
      isTruncated: v.boolean(),
    }),
    executionTime: v.number(),
  }).index("by_name_and_ts", ["name", "ts"]),
  _udf_config: defineTable({
    serverVersion: v.string(),
    importPhaseRngSeed: v.bytes(),
    // Nanoseconds since the Unix epoch.
    importPhaseUnixTimestamp: v.int64(),
  }),
  _schemas: defineTable(schemaMetadata).index("by_state", ["state"]),
  _schema_validations: defineTable({
    schemaId: v.id("_schemas"),
    tableName: v.string(),
    validatorHash: v.optional(v.string()),
    state: v.union(
      v.object({ state: v.literal("pending") }),
      v.object({ state: v.literal("valid") }),
      v.object({ state: v.literal("failed"), error: v.string() }),
    ),
  }).index("by_schema_id_and_table_name", ["schemaId", "tableName"]),
  _schema_validation_progress: defineTable({
    validationId: v.id("_schema_validations"),
    numDocsValidated: v.int64(),
    totalDocs: v.union(v.int64(), v.null()),
  }).index("by_validation_id", ["validationId"]),
  _log_sinks: integrationsTable,
  _s3_export_state: defineTable({
    configId: v.id("_log_sinks"),
    checkpoint: v.object({
      progress: s3ExportProgress,
    }),
  }).index("by_config_id", ["configId"]),
  _backend_state: backendStateTable,
  _snapshot_imports: snapshotImportsTable,
  _aws_lambda_versions: awsLambdaVersionsTable,
  // Fields with `v.optional` are missing on documents written before they
  // were added.
  _backend_info: defineTable({
    org: v.int64(),
    project: v.int64(),
    instance: v.int64(),
    deploymentType: v.union(
      v.literal("dev"),
      v.literal("prod"),
      v.literal("preview"),
      v.literal("custom"),
    ),
    deploymentRef: v.optional(v.union(v.string(), v.null())),
    streamingExportEnabled: v.optional(v.boolean()),
    provisionConcurrency: v.optional(v.union(v.int64(), v.null())),
    logStreamingEnabled: v.optional(v.boolean()),
    projectName: v.optional(v.union(v.string(), v.null())),
    projectSlug: v.optional(v.union(v.string(), v.null())),
    auditLogRetentionDays: v.optional(v.union(v.int64(), v.null())),
    sendLogsToClient: v.optional(v.union(v.boolean(), v.null())),
    customAuditLogsInLogStreamsConfigEnabled: v.optional(
      v.union(v.boolean(), v.null()),
    ),
    aiGatewayDisabled: v.optional(v.union(v.boolean(), v.null())),
    periodicBackupsEnabled: v.optional(v.union(v.boolean(), v.null())),
    maxCloudBackups: v.optional(v.union(v.int64(), v.null())),
    defaultUdfRuntime: v.optional(v.union(v.literal("v8"), v.literal("wasm"))),
  }),
});
